mapper.select:
select * from (select a.balance_account_id,a.project_id,a.lease_item_id,a.document_category,a.change_date, a.change_amount,a.before_change_amount,hli.full_name,hli.lease_item_type, abs( nvl(a.before_change_amount,0) -abs(nvl(a.change_amount,0)) ) now_amount, (select meaning from sys_code_value_b_v where code = 'HLS.COLLATERAL_TYPE' and code_value = hli.LEASE_ITEM_TYPE) lease_item_type_n, pp.contract_number, pp.unit_id, (select fou.unit_name from fnd_org_unit fou where fou.unit_id=pp.unit_id) as unit_id_n, pp.contract_name, (select bp_name from hls_bp_master where bp_id=pp.tenant_id) as tenant_id_n, (select sum(hlid.INITIAL_MORTGAGE_PLEDGE_AMOUNT) as EVALUATION_VALUE from hls_lease_item_detail hlid where hlid.lease_item_id = hli.lease_item_id)INITIAL_MORTGAGE_PLEDGE_AMOUNT, hli.valuation_date from hls_off_balance_account a,hls_lease_item hli ,prj_project pp where a.lease_item_id = hli.lease_item_id and a.project_id = pp.project_id) t
1=1
and t.contract_number = #{contractNumber}
and t.contract_name like concat(concat('%',#{contractName}),'%')
and t.change_date >= #{changeDateFrom}
and t.change_date <= #{changeDateTo}
and t.tenant_id_n like concat(concat('%',#{tenantIdN}),'%')
and t.lease_item_type = #{leaseItemType}
and t.unit_id = #{unitId}
order by t.CHANGE_DATE desc

select * from (select a.balance_account_id,a.project_id,a.lease_item_id,a.document_category,a.change_date, a.change_amount,a.before_change_amount,hli.full_name,hli.lease_item_type, abs( nvl(a.before_change_amount,0) -abs(nvl(a.change_amount,0)) ) now_amount, (select meaning from sys_code_value_b_v where code = 'HLS.COLLATERAL_TYPE' and code_value = hli.LEASE_ITEM_TYPE) lease_item_type_n, pp.contract_number, pp.unit_id, (select fou.unit_name from fnd_org_unit fou where fou.unit_id=pp.unit_id) as unit_id_n, pp.contract_name, (select bp_name from hls_bp_master where bp_id=pp.tenant_id) as tenant_id_n, (select sum(hlid.INITIAL_MORTGAGE_PLEDGE_AMOUNT) as EVALUATION_VALUE from hls_lease_item_detail hlid where hlid.lease_item_id = hli.lease_item_id)INITIAL_MORTGAGE_PLEDGE_AMOUNT, hli.valuation_date from hls_off_balance_account a,hls_lease_item hli ,prj_project pp where a.lease_item_id = hli.lease_item_id and a.project_id = pp.project_id and a.creation_date = (select max(b.creation_date) from hls_off_balance_account b where b.lease_item_id = a.lease_item_id)) t
1=1
and t.contract_number = #{contractNumber}
and t.contract_name like concat(concat('%',#{contractName}),'%')
and t.change_date >= #{changeDateFrom}
and t.change_date <= #{changeDateTo}
and t.tenant_id_n like concat(concat('%',#{tenantIdN}),'%')
and t.lease_item_type = #{leaseItemType}
and t.unit_id = #{unitId}
order by t.CHANGE_DATE desc
